// Parsear orden de transmisión. Entrada: salida de Gmail Get Message (text, html, from.value[].address)
const email = $input.first().json;
// Get Message: text (plano), html. Trigger: body, textPlain, textHtml, snippet
const rawText = email.text ?? email.body ?? email.textPlain ?? email.textHtml ?? '';
const subject = email.subject ?? email.Subject ?? '';
// Get Message: from.value[0].address, from.text. Trigger: from.value, From
const emailFrom = email.from?.value?.[0]?.address ?? email.from?.text ?? email.from?.value ?? email.From ?? null;

const cleanHTML = (text) => {
  if (!text) return '';
  return String(text)
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();
};
// Preferir texto plano (Get Message text); si no, usar HTML limpiado o snippet
const bodyRaw = rawText || (email.html ? cleanHTML(email.html) : '') || email.snippet || '';
const bodyFinal = bodyRaw.replace(/[^\S\n\r]+/g, ' ').trim();

// Normalizar nombre de campo (quitar *, /, espacios)
const norm = (s) => (s || '').toLowerCase().replace(/[*\/]/g, '').replace(/\s+/g, ' ').trim();

const parsed = {};
const lines = bodyFinal.split(/[\n\r]+/);
for (const line of lines) {
  const trimmed = line.trim();
  if (!trimmed || /^[=\-\s\[\]]+$/.test(trimmed)) continue;
  const colonIdx = trimmed.indexOf(':');
  if (colonIdx <= 0) continue;
  const fieldName = norm(trimmed.slice(0, colonIdx));
  const value = trimmed.slice(colonIdx + 1).trim();
  if (fieldName && value) parsed[fieldName] = value;
}

const find = (...keys) => {
  for (const key of keys) {
    const n = norm(key);
    const found = Object.keys(parsed).find(k => k === n || k.includes(n) || n.includes(k));
    if (found) return parsed[found];
  }
  return null;
};

const extract = (text, patterns) => {
  if (!text) return null;
  for (const p of patterns) {
    const m = text.match(typeof p === 'string' ? new RegExp(p, 'gi') : p);
    if (m && m[1]) return m[1].trim();
  }
  return null;
};

const cliente = find('Cliente', 'Cliente*') || extract(bodyFinal, [/Cliente\s*\*?\s*[:\s]+([^\n]+?)(?=\n|Campaña|Producto|$)/i, /Cliente\s*[:\s]+(.+?)(?=\n|$)/i]);
const campaña = find('Campaña', 'Campaña / Producto', 'Producto', 'Campaña/Producto') || extract(bodyFinal, [/Campaña\s*\/\s*Producto\s*\*?\s*[:\s]+([^\n]+)/i, /Producto\s*\*?\s*[:\s]+([^\n]+)/i, /Campaña\s*\*?\s*[:\s]+([^\n]+)/i]);
const emisora = find('Emisora', 'Emisora / Estación', 'Estación', 'Emisora/Estación') || extract(bodyFinal, [/Emisora\s*\/\s*Estación\s*\*?\s*[:\s]+([^\n]+)/i, /Estación\s*\*?\s*[:\s]+([^\n]+)/i, /Emisora\s*\*?\s*[:\s]+([^\n]+)/i]);
const cuñasDiarias = find('Cuñas diarias', 'Cuñas diarias*', 'Cuñas diaria') || extract(bodyFinal, [/Cuñas\s*\*?\s*diarias\s*[:\s]+(\d+)/i, /Cuñas\s+por\s+d[ií]a\s*[:\s]+(\d+)/i, /Cuñas\s+diarias\s*\*?\s*[:\s]+(\d+)/i]);
const totalContratadas = find('Total de cuñas contratadas', 'Total cuñas contratadas', 'Total contratadas', 'Total cuñas') || extract(bodyFinal, [/Total\s+de\s+cuñas\s+contratadas\s*\*?\s*[:\s]+(\d+)/i, /Total\s+cuñas\s+contratadas\s*[:\s]+(\d+)/i, /Total\s+contratadas\s*[:\s]+(\d+)/i, /Total\s+cuñas\s*[:\s]+(\d+)/i, /Total\s*[:\s]+(\d+)/i]);

let periodoInicio = find('Fecha inicio', 'Periodo inicio', 'Fecha inicio*');
let periodoFin = find('Fecha fin', 'Periodo fin', 'Fecha fin*');
if (!periodoInicio || !periodoFin) {
  const periodoStr = extract(bodyFinal, [/Periodo\s*[:\s]+([^\n]+)/i]) || bodyFinal.match(/(\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4})\s*[-–]\s*(\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4})/);
  if (periodoStr) {
    const str = Array.isArray(periodoStr) ? periodoStr[0] : periodoStr;
    const fechas = str.split(/[-–]/).map(f => f.trim());
    if (fechas.length >= 2) {
      periodoInicio = periodoInicio || fechas[0];
      periodoFin = periodoFin || fechas[1];
    }
  }
}

const spotId = find('Spot ID', 'ID') || extract(bodyFinal, [/Spot\s*ID\s*[:\s]+([^\n]+)/i]);
const spotName = find('Spot Name', 'Nombre') || extract(bodyFinal, [/Spot\s*Name\s*[:\s]+([^\n]+)/i]);
const emailCliente = emailFrom || find('Email');
const agencia = find('Agencia') || extract(bodyFinal, [/Agencia\s*[:\s]+([^\n]+)/i]);
const duracionSeg = find('Duración') || extract(bodyFinal, [/Duraci[oó]n\s*[:\s]+(\d+)/i]);
const horario = find('Horario') || extract(bodyFinal, [/Horario\s*[:\s]+([^\n]+)/i]);
const ciudad = find('Ciudad') || extract(bodyFinal, [/Ciudad\s*[:\s]+([^\n]+)/i]);

if (!cliente || !campaña || !emisora || !cuñasDiarias || !totalContratadas) {
  return [{
    json: {
      error: true,
      message: 'Faltan campos requeridos en la orden',
      campos_encontrados: { cliente: !!cliente, campaña: !!campaña, emisora: !!emisora, cuñasDiarias: !!cuñasDiarias, totalContratadas: !!totalContratadas },
      body_preview: bodyFinal.substring(0, 500)
    }
  }];
}

const parseDate = (dateStr) => {
  if (!dateStr) return null;
  const s = String(dateStr).trim();
  const ddmmyyyy = s.match(/(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})/);
  if (ddmmyyyy) return `${ddmmyyyy[3]}-${ddmmyyyy[2].padStart(2, '0')}-${ddmmyyyy[1].padStart(2, '0')}`;
  const yyyymmdd = s.match(/(\d{4})[\/\-](\d{1,2})[\/\-](\d{1,2})/);
  if (yyyymmdd) return `${yyyymmdd[1]}-${yyyymmdd[2].padStart(2, '0')}-${yyyymmdd[3].padStart(2, '0')}`;
  return null;
};

return [{
  json: {
    cliente,
    campaña,
    spot_id: spotId,
    spot_name: spotName,
    emisora,
    cuñas_diarias: parseInt(cuñasDiarias, 10) || 0,
    total_contratadas: parseInt(totalContratadas, 10) || 0,
    periodo_inicio: parseDate(periodoInicio),
    periodo_fin: parseDate(periodoFin),
    estado: 'activa',
    email_cliente: emailCliente,
    agencia: agencia,
    duracion_seg: duracionSeg ? parseInt(duracionSeg, 10) : null,
    horario: horario,
    ciudad: ciudad,
    email_id: email.id,
    email_subject: subject,
    email_from: emailFrom,
    error: false
  }
}];
